mapper.select:
SELECT R.recv_seq AS linkRawSn, R.recv_dt AS clctDt, CASE CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(R.recv_content,'<#>',2),'<#>',-1) AS UNSIGNED) WHEN 1 THEN 'EMS_TX' WHEN 4 THEN 'VMS' WHEN 11 THEN 'PBX' WHEN 13 THEN 'EMS_PIDS' WHEN 16 THEN 'SCADA_SEC' ELSE NULL END AS linkSysCd, L.LINK_SYS_NM AS linkSysNm, R.recv_type AS msgTypeNm, '수신' AS trsmDrctNm, NULL AS souIpAddr, NULL AS souPortNo, R.recv_type AS dataSeCd, 'RECEIVED' AS clctSttsCd, NULL AS errCn FROM raw_receive_log R LEFT JOIN web_link_sys_info L ON L.LINK_SYS_CD=(CASE CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(R.recv_content,'<#>',2),'<#>',-1) AS UNSIGNED) WHEN 1 THEN 'EMS_TX' WHEN 4 THEN 'VMS' WHEN 11 THEN 'PBX' WHEN 13 THEN 'EMS_PIDS' WHEN 16 THEN 'SCADA_SEC' ELSE NULL END) WHERE CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(R.recv_content,'<#>',2),'<#>',-1) AS UNSIGNED) IN #{id} AND R.recv_dt >= #{startDt} AND R.recv_dt <= #{endDt}
AND CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(R.recv_content,'<#>',2),'<#>',-1) AS UNSIGNED) = (CASE #{linkSysCd} WHEN 'EMS_TX' THEN 1 WHEN 'VMS' THEN 4 WHEN 'PBX' THEN 11 WHEN 'EMS_PIDS' THEN 13 WHEN 'SCADA_SEC' THEN 16 ELSE -1 END)
AND (R.recv_type LIKE CONCAT('%',#{keyword},'%') OR R.recv_content LIKE CONCAT('%',#{keyword},'%')) ORDER BY R.recv_dt DESC,R.recv_seq DESC LIMIT 500
